ow:0 14px 40px rgba(20,30,70,.05)}.tool-sidebar{position:sticky;top:88px;max-height:calc(100vh - 108px);overflow:auto}.tool-sidebar a{display:block;padding:9px 10px;margin:3px 0;border-radius:9px;text-decoration:none;color:#536075;font-size:13px;font-weight:700}.tool-sidebar a:hover,.tool-sidebar a.active{background:#f0efff;color:#635bff}.tool-main input{width:100%;padding:12px;border:1px solid #dfe4ec;border-radius:10px;margin:8px 0 14px}.tool-main button{padding:11px 16px;margin:0 6px 12px 0;border:0;border-radius:10px;background:#635bff;color:white;font-weight:700;cursor:pointer}.tool-main pre{background:#f7f8fb;border:1px solid #e5e9f0;border-radius:12px;padding:16px;white-space:pre-wrap;word-break:break-all}@media(max-width:800px){.tool-layout{grid-template-columns:1fr}.tool-sidebar{position:static;max-height:330px}}</style><script>let uuids=[];function makeUUID(){if(window.crypto&&crypto.randomUUID)return crypto.randomUUID();return'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0,v=c==='x'?r:r&3|8;return v.toString(16)})}document.getElementById('generate').onclick=()=>{const n=Math.min(100,Math.max(1,parseInt(document.getElementById('count').value)||1));uuids=Array.from({length:n},makeUUID);document.getElementById('output').textContent=uuids.join('\n')};document.getElementById('copy').onclick=async()=>{if(!uuids.length)document.getElementById('generate').click();await navigator.clipboard.writeText(uuids.join('\n'))}</script><?php require_once __DIR__.'/../footer.php'; ?>